/* BIG LWA role stickers: account-owned placements, safe against live profile geometry. */
(()=>{
'use strict';
if(window.BigLWARoleStickers)return;
const KEY='biglwaRoleStickerPositionsV1';
const assets=Object.freeze({Producer:'producer.png',Student:'student.png',Writer:'writer.png',Director:'director.png',Creator:'creator.png',Creative:'creator.png',Stylist:'stylisy.png',Founder:'founder.png',Researcher:'researcher.png'});
const $=(s,r=document)=>r.querySelector(s),all=(s,r=document)=>Array.from(r.querySelectorAll(s));
const owner=()=>String(window.BigLWAAccountStorage?.uid||'');
const allowed=()=>!!owner()&&!window.__biglwaPublicStorageView&&!document.documentElement.classList.contains('biglwa-preview-mode');
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function normalize(raw){const out={};for(const role of Object.keys(assets)){const p=raw?.[role];if(p&&['banner','scoreboard'].includes(p.surface)&&Number.isFinite(p.x)&&Number.isFinite(p.y))out[role]={surface:p.surface,x:clamp(p.x,0,1),y:clamp(p.y,0,1)}}return out}
function read(){if(!allowed())return {};try{return normalize(JSON.parse(localStorage.getItem(KEY)||'{}'))}catch{return {}}}
function save(role,p){if(!allowed())throw Error('Sign in to save sticker positions.');const state=read();state[role]=p;localStorage.setItem(KEY,JSON.stringify(normalize(state)))}
function hash(s){let h=2166136261;for(const c of s){h=Math.imul(h^c.charCodeAt(0),16777619)}return h>>>0}
function random(seed){return ((Math.imul(seed,1664525)+1013904223)>>>0)/4294967296}
function overlap(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function fit(w,h,size,blocked,want){const out=[];if(w<size+12||h<size+12)return null;const push=(x,y)=>{const r={x,y,w:size,h:size};if(x<6||y<6||x+size>w-6||y+size>h-6||blocked.some(b=>overlap(r,b)))return;out.push(r)};push(clamp(want.x*w-size/2,6,w-size-6),clamp(want.y*h-size/2,6,h-size-6));for(let y=6;y<=h-size-6;y+=8)for(let x=6;x<=w-size-6;x+=8)push(x,y);out.sort((a,b)=>Math.hypot(a.x+size/2-want.x*w,a.y+size/2-want.y*h)-Math.hypot(b.x+size/2-want.x*w,b.y+size/2-want.y*h));return out[0]||null}
let hosts={},layers={},nodes=new Map(),occupied={},frame=0,drag=null,observer=null,observed=[],status=null,pendingRole='',pendingOwner='',tray=null;
const surfaceHost=(card)=>({banner:card,scoreboard:$('.biglwa-profile-scoreboard',card)});
function rectFor(node,host,pad=5){const a=node.getBoundingClientRect(),h=host.getBoundingClientRect();if(a.width<1||a.height<1||a.right<=h.left||a.left>=h.right||a.bottom<=h.top||a.top>=h.bottom)return null;return {x:a.left-h.left-pad,y:a.top-h.top-pad,w:a.width+2*pad,h:a.height+2*pad}}
function obstacles(host,surface){const selectors=surface==='banner'?'.profile-identity-rail,.profile-name-line,.bio,.biglwa-profile-bio-roles,.biglwa-stories-ribbon,.real-rank,#editProfileBtn,.profile-card .window-lights,.biglwa-community-badges,.biglwa-profile-scoreboard,button:not(.lwa-role-sticker-handle),a,input,textarea':'.biglwa-scoreboard-header,.biglwa-score-clock,.biglwa-scoreboard-lights,[data-profile-stat],button:not(.lwa-role-sticker-handle),a';const result=all(selectors,host).filter(n=>!n.closest('.lwa-role-sticker-layer')&&(surface!=='banner'||!n.closest('.biglwa-profile-scoreboard')||n.matches('.biglwa-profile-scoreboard'))).map(n=>rectFor(n,host)).filter(Boolean);if(surface==='scoreboard'){const stat=$('.stats',host);if(stat){const r=rectFor(stat,host,0);if(r)result.push({x:r.x+r.w*.34,y:r.y+r.h*.52,w:r.w*.32,h:r.h*.48})}}return result}
function layer(host,surface){let n=Array.from(host.children).find(c=>c.classList.contains('lwa-role-sticker-layer'));if(!n){n=document.createElement('div');n.className='lwa-role-sticker-layer';n.dataset.stickerSurface=surface;host.append(n)}return n}
function report(msg){if(status)status.textContent=msg}
function place(role,want,excludeRole=role){for(const surface of [want.surface,want.surface==='banner'?'scoreboard':'banner']){const h=hosts[surface];if(!h||!h.getClientRects().length)continue;const bounds=h.getBoundingClientRect();if(bounds.width<100||bounds.height<80)continue;const blocked=obstacles(h,surface).concat(Object.entries(occupied).filter(([r,p])=>r!==excludeRole&&p.surface===surface).map(([r,p])=>p.rect));for(const size of [Math.min(82,Math.max(52,Math.floor(bounds.width*.16))),58,48]){const r=fit(bounds.width,bounds.height,size,blocked,want);if(r)return {surface,rect:r,x:(r.x+r.w/2)/bounds.width,y:(r.y+r.h/2)/bounds.height}}}return null}
function position(node,p){const root=layers[p.surface];if(node.parentElement!==root)root.append(node);node.style.left=p.x*100+'%';node.style.top=p.y*100+'%';node.style.width=p.rect.w+'px';node.style.height=p.rect.h+'px';node.hidden=false}
function defaultPosition(role,index){const seed=hash(owner()+':'+role),side=random(seed)<.5?'banner':'scoreboard';return {surface:side,x:.15+.7*random(seed^12345),y:.12+.76*random(seed^96321)}}
function make(role){const node=document.createElement('div');node.className='lwa-role-sticker';node.dataset.role=role;node.style.setProperty('--sticker-tilt',((hash(role)%13)-6)+'deg');const img=document.createElement('img');img.src='/'+assets[role];img.alt=role==='Creative'?'Creator':role;img.loading='lazy';img.decoding='async';img.draggable=false;img.addEventListener('error',()=>{node.dataset.broken='1';schedule()},{once:true});const handle=document.createElement('button');handle.type='button';handle.className='lwa-role-sticker-handle';handle.textContent='⠿';handle.title='Drag '+role+' sticker · arrow keys to move; Enter to switch surface';handle.setAttribute('aria-label','Move '+role+' sticker. Use arrow keys or Enter to switch surface.');node.append(img,handle);
handle.addEventListener('pointerdown',e=>{if(e.button!==0||!allowed())return;e.preventDefault();e.stopPropagation();const r=node.getBoundingClientRect();drag={role,node,handle,id:e.pointerId,owner:owner(),startX:e.clientX,startY:e.clientY,dx:e.clientX-r.left-r.width/2,dy:e.clientY-r.top-r.height/2,ghost:null};handle.setPointerCapture?.(e.pointerId)});
handle.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(!drag.ghost&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4){const ghost=node.cloneNode(true);ghost.querySelector('button')?.remove();ghost.className='lwa-role-sticker-ghost';ghost.style.width=node.offsetWidth+'px';document.body.append(ghost);drag.ghost=ghost;node.classList.add('is-moving')}if(drag.ghost){drag.ghost.style.left=(e.clientX-drag.dx)+'px';drag.ghost.style.top=(e.clientY-drag.dy)+'px'}});
handle.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag;finishDrag();if(!d.ghost||d.owner!==owner()||!allowed())return;const x=e.clientX-d.dx,y=e.clientY-d.dy;let target=Object.entries(hosts).reverse().find(([k,h])=>{if(!h)return false;const r=h.getBoundingClientRect();return x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom});if(!target){report('Drop inside the profile banner or scoreboard.');return}const [surface,h]=target,r=h.getBoundingClientRect();commit(role,{surface,x:clamp((x-r.left)/r.width,0,1),y:clamp((y-r.top)/r.height,0,1)})});
handle.addEventListener('pointercancel',finishDrag);handle.addEventListener('lostpointercapture',finishDrag);handle.addEventListener('keydown',e=>{const p=occupied[role];if(!p)return;const delta={ArrowLeft:[-.1,0],ArrowRight:[.1,0],ArrowUp:[0,-.1],ArrowDown:[0,.1]}[e.key];if(!delta&&e.key!=='Enter')return;e.preventDefault();e.stopPropagation();commit(role,{surface:delta?p.surface:p.surface==='banner'?'scoreboard':'banner',x:clamp(p.x+(delta?.[0]||0),0,1),y:clamp(p.y+(delta?.[1]||0),0,1)})});handle.addEventListener('click',e=>{e.preventDefault();e.stopPropagation()});return node}
function finishDrag(){if(!drag)return;drag.ghost?.remove();drag.node.classList.remove('is-moving');drag=null}
function commit(role,want){const p=place(role,want);if(!p||p.surface!==want.surface){report('No clear space there; try another area.');return}try{save(role,{surface:p.surface,x:p.x,y:p.y});occupied[role]=p;if(!nodes.has(role))nodes.set(role,make(role));layers[p.surface]=layer(hosts[p.surface],p.surface);position(nodes.get(role),p);report('Sticker position saved locally; account sync will follow.');closeTray();schedule()}catch(e){report(e.message)}}
function clear(){for(const n of nodes.values())n.remove();nodes.clear();for(const n of Object.values(layers))n?.remove();layers={};occupied={};finishDrag()}
function draw(){frame=0;if(drag)return;const card=$('#studioApp .profile-card:not(.profile-is-editing)');const api=window.BigLWACommunityProfile;if(!allowed()||!card||api?.syncStatus!=='ready'){clear();return}const data=api.get(),saved=read();const roles=data.showRoles?data.roles.filter(r=>Object.hasOwn(assets,r)&&saved[r]):[];hosts=surfaceHost(card);if(!roles.length&&!pendingRole){clear();return}const next=[hosts.banner,hosts.scoreboard].filter(Boolean);if(next.length!==observed.length||next.some((n,i)=>n!==observed[i])){observer?.disconnect();observed=next;if(typeof ResizeObserver==='function'){observer=new ResizeObserver(schedule);next.forEach(n=>observer.observe(n))}}for(const [key,h] of Object.entries(hosts))if(h)layers[key]=layer(h,key);for(const [r,n] of nodes)if(!roles.includes(r)){n.remove();nodes.delete(r)}const badges=$('#biglwaCommunityRoleBadges',card);if(badges){status=$('.lwa-role-sticker-status',badges);if(!status){status=document.createElement('span');status.className='lwa-role-sticker-status';status.setAttribute('role','status');badges.append(status)}}occupied={};for(const role of roles){let n=nodes.get(role);if(!n){n=make(role);nodes.set(role,n)}const p=n.dataset.broken?null:place(role,saved[role]);if(p){occupied[role]=p;position(n,p)}else{n.remove()}const badge=all('.biglwa-community-badge',badges||card).find(b=>b.textContent.trim()===role);if(badge)badge.classList.remove('lwa-role-has-sticker')}}

function closeTray(){pendingRole='';pendingOwner='';tray?.remove();tray=null;document.querySelectorAll('.lwa-sticker-safe-zone').forEach(n=>n.remove())}
function mountCase(){const host=$('#trophyCaseVersion .trophy-display-case');if(!host||!allowed())return;const api=window.BigLWACommunityProfile;if(api?.syncStatus!=='ready')return;let panel=$('.lwa-sticker-case',host);if(!panel){panel=document.createElement('section');panel.className='lwa-sticker-case';host.prepend(panel)}const data=api.get(),saved=read(),roles=data.roles.filter(r=>Object.hasOwn(assets,r));const sig=JSON.stringify([roles,data.showRoles,saved]);if(panel.dataset.signature===sig)return;panel.dataset.signature=sig;panel.replaceChildren();const title=document.createElement('h3');title.textContent='Role stickers';const hint=document.createElement('p');hint.textContent='Take out a selected role sticker and place it on your profile. These are self-described roles, not earned awards.';panel.append(title,hint);const grid=document.createElement('div');grid.className='lwa-sticker-case-grid';for(const role of roles){const card=document.createElement('div'),img=document.createElement('img'),b=document.createElement('button');img.src='/'+assets[role];img.alt=role;img.loading='lazy';b.type='button';b.textContent=saved[role]?'Move sticker':'Take out';b.disabled=!data.showRoles;b.onclick=()=>{closeTray();pendingRole=role;pendingOwner=owner();$('#moduleBack')?.click();schedule();requestAnimationFrame(()=>{$('#studioApp .profile-card')?.scrollIntoView({block:'center'})})};card.append(img,b);if(saved[role]){const put=document.createElement('button');put.type='button';put.textContent='Return to case';put.onclick=()=>{if(!allowed())return;const next=read();delete next[role];localStorage.setItem(KEY,JSON.stringify(next));mountCase();schedule()};card.append(put)}grid.append(card)}if(!roles.length){const p=document.createElement('p');p.textContent='Choose a role with a sticker in Edit profile first.';grid.append(p)}panel.append(grid)}
function drawTray(){if(!pendingRole)return;if(!allowed()||owner()!==pendingOwner){closeTray();return}const card=$('#studioApp .profile-card:not(.profile-is-editing)');if(!card||!card.getClientRects().length)return;hosts=surfaceHost(card);if(!tray){tray=document.createElement('aside');tray.className='lwa-sticker-tray';const label=document.createElement('strong');label.textContent='Place '+pendingRole+' sticker';const img=document.createElement('img');img.src='/'+assets[pendingRole];img.alt=pendingRole;img.draggable=false;const hint=document.createElement('small');hint.textContent='Drag onto the banner or scoreboard, or select a dashed safe area.';const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel';cancel.onclick=closeTray;tray.append(label,img,hint,cancel);document.body.append(tray);let pointer=null;img.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();pointer=e.pointerId;img.setPointerCapture?.(pointer);img.classList.add('is-dragging')});img.addEventListener('pointermove',e=>{if(pointer!==e.pointerId)return;const r=tray.getBoundingClientRect();img.style.transform='translate('+(e.clientX-r.left-img.offsetLeft-img.offsetWidth/2)+'px,'+(e.clientY-r.top-img.offsetTop-img.offsetHeight/2)+'px)'});img.addEventListener('pointerup',e=>{if(pointer!==e.pointerId)return;pointer=null;img.style.transform='';img.classList.remove('is-dragging');const found=Object.entries(hosts).reverse().find(([k,h])=>{if(!h)return false;const r=h.getBoundingClientRect();return e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom});if(found){const [surface,h]=found,r=h.getBoundingClientRect();commit(pendingRole,{surface,x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height})}});img.addEventListener('pointercancel',()=>{pointer=null;img.style.transform='';img.classList.remove('is-dragging')})}
for(const n of document.querySelectorAll('.lwa-sticker-safe-zone'))n.remove();for(const [surface,h] of Object.entries(hosts)){if(!h||!h.getClientRects().length)continue;const p=place(pendingRole,{surface,x:.5,y:.5});if(!p||p.surface!==surface)continue;const l=layers[surface]=layer(h,surface);const b=document.createElement('button');b.type='button';b.className='lwa-sticker-safe-zone';b.textContent='+';b.title='Place sticker on '+surface;b.setAttribute('aria-label',b.title);b.style.cssText='left:'+p.x*100+'%;top:'+p.y*100+'%;width:'+p.rect.w+'px;height:'+p.rect.h+'px';b.onclick=()=>commit(pendingRole,p);l.append(b)}}

function schedule(){if(!frame)frame=requestAnimationFrame(()=>{draw();mountCase();drawTray()})}
document.addEventListener('biglwa:community-profile-updated',schedule);document.addEventListener('biglwa:session-verified',schedule);document.addEventListener('biglwa:module-close',schedule);document.addEventListener('biglwa:module-open',schedule);document.addEventListener('click',e=>{if(e.target.closest?.('[data-trophy-version]'))schedule()});window.addEventListener('biglwa:identity-updated',schedule);window.addEventListener('resize',schedule);window.addEventListener('biglwa:account-storage-status',()=>{if(!drag)schedule()});
new MutationObserver(records=>{if(records.some(r=>!r.target.closest?.('.lwa-role-sticker-layer,.lwa-role-sticker-status')&&Array.from(r.addedNodes).some(n=>n.nodeType===1&&!n.matches?.('.lwa-role-sticker-layer,.lwa-role-sticker-status,.lwa-role-sticker-ghost')&&(n.matches?.('.profile-card,.biglwa-profile-scoreboard,#biglwaCommunityRoleBadges,.biglwa-community-badge,.biglwa-stories-ribbon,.biglwa-score-clock,#trophyCaseVersion,.trophy-display-case')||n.querySelector?.('.profile-card,.biglwa-profile-scoreboard')))))schedule()}).observe(document.documentElement,{childList:true,subtree:true});
window.BigLWARoleStickers=Object.freeze({refresh:schedule,fit,normalize});schedule();
})();